// GENERATED by scripts/sync-setup-check-shared.ts — edit the source under src/, then run `npm run shared:sync`.
// SHARED, dependency-free (synced to supabase/functions/_shared/tradeScreenshot by `npm run shared:sync`).
//
// Turns the vision model's structured output into a reading the journal can
// show for review. The model only REPORTS what it sees; everything here is
// deterministic: the symbol is mapped to the instrument catalog, impossible
// values are dropped, and anything suspicious is flagged. Missing values stay
// null. Nothing is calculated to fill a gap.

import { NUMBER_FIELDS, SCREENSHOT_KINDS, VALUE_SOURCES, type NumberField, type ScreenshotKind, type ValueSource } from './schema.ts';

export interface CatalogEntry {
  symbol: string;
  name: string;
  tickSize: number;
  pointValue: number;
}

export interface ReadField<V> {
  value: V | null;
  /** 0–1 (after checks). */
  confidence: number;
  evidence: string;
  source: ValueSource;
  /** Reasons the trader should look at this value (never hidden). */
  flags: string[];
}

export interface TradeReading {
  kind: ScreenshotKind;
  legible: boolean;
  platform: ReadField<string>;
  /** Mapped to the instrument catalog; `raw` keeps what the screenshot showed. */
  instrument: ReadField<string> & { raw: string | null };
  direction: ReadField<'long' | 'short'>;
  entryPrice: ReadField<number>;
  exitPrice: ReadField<number>;
  stopPrice: ReadField<number>;
  targetPrice: ReadField<number>;
  quantity: ReadField<number>;
  realizedPnl: ReadField<number>;
  accountBalance: ReadField<number>;
  drawdown: ReadField<number>;
  levels: { label: string; price: number; kind: string }[];
  notes: string;
  warnings: string[];
  /** Enough to pre-fill a journal entry (a fill and an instrument). */
  usable: boolean;
}

/** Below this the value is treated as not visible. */
export const MIN_CONFIDENCE = 0.35;
/** Below this the value is shown but must be checked. */
export const REVIEW_CONFIDENCE = 0.7;

const MONTH = /[FGHJKMNQUVXZ]\d{1,2}$/;
const clean = (s: string) => s.trim().toUpperCase().replace(/\s+/g, ' ');
const isObj = (v: unknown): v is Record<string, unknown> => !!v && typeof v === 'object' && !Array.isArray(v);
/** Mask account-number-like tokens and emails the model should not have returned. */
export function redact(text: string): string {
  return text
    .replace(/[^\s@]+@[^\s@]+\.[a-z]{2,}/gi, '[email]')
    .replace(/\b(?=[A-Z0-9-]*\d{4,})(?=[A-Z0-9-]*[A-Z-])[A-Z0-9][A-Z0-9-]{5,}\b/gi, (m) => `••••${m.replace(/[^A-Za-z0-9]/g, '').slice(-4)}`);
}
const str = (v: unknown, max: number) => (typeof v === 'string' ? redact(v.replace(/[\u0000-\u001f]/g, ' ')).slice(0, max).trim() : '');
const clamp01 = (n: unknown) => (typeof n === 'number' && Number.isFinite(n) ? Math.max(0, Math.min(1, n)) : 0);

/** "MNQZ6", "MNQ1!", "/MES", "CME_MINI:ES1!", "E-mini S&P 500" → catalog symbol (or null). */
export function mapInstrument(raw: string | null, catalog: readonly CatalogEntry[]): string | null {
  if (!raw) return null;
  const symbols = new Set(catalog.map((c) => c.symbol));
  let s = clean(raw).replace(/^[/@]/, '');
  if (s.includes(':')) s = s.split(':').pop()!;
  s = s.split(' ')[0].replace(/\d!$/, '').replace(/!$/, '');
  if (symbols.has(s)) return s;
  const noMonth = s.replace(MONTH, '');
  if (noMonth !== s && symbols.has(noMonth)) return noMonth;
  // Full contract names ("Micro E-mini Nasdaq-100").
  const byName = catalog.find((c) => clean(c.name) === clean(raw));
  return byName ? byName.symbol : null;
}

/** True when the price is a whole number of ticks (tolerant of float noise). */
export function onTick(price: number, tick: number): boolean {
  const k = price / tick;
  return Math.abs(k - Math.round(k)) < 1e-6;
}

function readField<V>(raw: unknown, accept: (v: unknown) => V | null, flagsOut: string[], label: string): ReadField<V> {
  const o = isObj(raw) ? raw : {};
  const source = (VALUE_SOURCES as readonly string[]).includes(String(o.source)) ? (o.source as ValueSource) : 'not_visible';
  let confidence = clamp01(o.confidence);
  let value = o.value == null ? null : accept(o.value);
  const flags: string[] = [];
  if (o.value != null && value == null) flags.push(`${label}: the reading was not a valid value and was dropped.`);
  if (value != null && source === 'not_visible') {
    value = null;
    flags.push(`${label}: reported without a visible source — not used.`);
  }
  if (value != null && confidence < MIN_CONFIDENCE) {
    flagsOut.push(`${label} was unclear on the screenshot — left empty.`);
    value = null;
  }
  if (value == null) confidence = 0;
  return { value, confidence, evidence: str(o.evidence, 140), source: value == null ? 'not_visible' : source, flags };
}

const positive = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) && v > 0 ? v : null);
const signed = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) ? v : null);
const flag = (f: ReadField<unknown>, msg: string, cap = 0.5) => {
  f.flags.push(msg);
  f.confidence = Math.min(f.confidence, cap);
};

/**
 * Validate and check a model reading. `raw` is untrusted (model output);
 * anything malformed becomes "not visible".
 */
export function normalizeTradeReading(raw: unknown, catalog: readonly CatalogEntry[]): TradeReading {
  const o = isObj(raw) ? raw : {};
  const warnings: string[] = [];
  const kind: ScreenshotKind = (SCREENSHOT_KINDS as readonly string[]).includes(String(o.screenshotType)) ? (o.screenshotType as ScreenshotKind) : 'unsupported';
  const legible = o.legible !== false;

  const platform = readField(o.platform, (v) => (typeof v === 'string' && v.trim() ? v.trim().slice(0, 30) : null), warnings, 'Platform');
  const instrRaw = readField(o.instrument, (v) => (typeof v === 'string' && v.trim() ? v.trim().slice(0, 30) : null), warnings, 'Instrument');
  const mapped = mapInstrument(instrRaw.value, catalog);
  const instrument = { ...instrRaw, raw: instrRaw.value, value: mapped };
  if (instrRaw.value && !mapped) {
    instrument.confidence = 0;
    instrument.source = 'not_visible';
    warnings.push(`Instrument “${instrRaw.value}” is not in the contract list — choose it yourself.`);
  }
  const direction = readField(o.direction, (v) => (v === 'long' || v === 'short' ? v : null), warnings, 'Direction');

  const nums = {} as Record<NumberField, ReadField<number>>;
  const labels: Record<NumberField, string> = {
    entryPrice: 'Entry',
    exitPrice: 'Exit',
    stopPrice: 'Stop',
    targetPrice: 'Target',
    quantity: 'Contracts',
    realizedPnl: 'Realized P&L',
    accountBalance: 'Account balance',
    drawdown: 'Drawdown',
  };
  for (const k of NUMBER_FIELDS) {
    const accept = k === 'realizedPnl' ? signed : k === 'quantity' ? (v: unknown) => (typeof v === 'number' && Number.isInteger(v) && v > 0 && v <= 500 ? v : null) : positive;
    nums[k] = readField(o[k], accept, warnings, labels[k]);
  }
  const { entryPrice, exitPrice, stopPrice, targetPrice, quantity, realizedPnl } = nums;

  // An exit exists only for a completed trade (an open position's "last price" is not an exit).
  if (kind !== 'completed_trade' && exitPrice.value != null) {
    warnings.push('No exit fill on this screenshot (the trade is not closed) — exit left empty.');
    exitPrice.value = null;
    exitPrice.confidence = 0;
    exitPrice.source = 'not_visible';
  }
  if (kind === 'pending_order') warnings.push('This shows an order that has not been filled — it is not a trade yet.');
  if (kind === 'open_position') warnings.push('This position is still open. Journal it after it closes, or enter the exit yourself.');
  if (kind === 'chart_only') warnings.push('Chart only — no position or fills are shown. Levels are drawings, not executed prices.');
  if (kind === 'account_dashboard') warnings.push('Account dashboard — no trade on this screenshot. Use Accounts → Import account screenshot for balances.');
  if (kind === 'unsupported') warnings.push('This does not look like a trading screenshot.');
  if (!legible) warnings.push('The image is hard to read — check every value or retake the screenshot.');

  // Drawings and typed notes are not executed prices.
  for (const f of [entryPrice, exitPrice]) if (f.value != null && (f.source === 'chart_drawing' || f.source === 'text_note' || f.source === 'position_tool')) flag(f, 'Read from a chart drawing/annotation, not a fill — confirm it.', 0.45);
  for (const f of [stopPrice, targetPrice]) if (f.value != null && (f.source === 'chart_drawing' || f.source === 'text_note')) flag(f, 'From a chart annotation, not an order — it may be an old or different plan.', 0.5);

  // Contract checks (tick size, sides of entry).
  const spec = catalog.find((c) => c.symbol === instrument.value);
  if (spec) for (const f of [entryPrice, exitPrice, stopPrice, targetPrice]) if (f.value != null && !onTick(f.value, spec.tickSize)) flag(f, `Not a valid ${spec.symbol} price (tick ${spec.tickSize}) — possibly misread.`, 0.4);
  const e = entryPrice.value;
  const d = direction.value;
  if (e != null && d) {
    if (stopPrice.value != null && (d === 'long' ? stopPrice.value >= e : stopPrice.value <= e)) flag(stopPrice, `Stop is on the wrong side of entry for a ${d}.`, 0.3);
    if (targetPrice.value != null && (d === 'long' ? targetPrice.value <= e : targetPrice.value >= e)) flag(targetPrice, `Target is on the wrong side of entry for a ${d}.`, 0.3);
  }

  // Shown P&L vs the prices (commissions or partial fills can explain small differences).
  if (spec && e != null && exitPrice.value != null && d && quantity.value != null && realizedPnl.value != null) {
    const pts = d === 'long' ? exitPrice.value - e : e - exitPrice.value;
    const calc = Math.round(pts * spec.pointValue * quantity.value * 100) / 100;
    const diff = Math.abs(calc - realizedPnl.value);
    if (diff > Math.max(10, Math.abs(calc) * 0.05)) {
      warnings.push(`Shown P&L (${realizedPnl.value.toFixed(2)}) differs from the prices × contracts (${calc.toFixed(2)}) — check entry, exit and size (or commissions / partial fills).`);
      for (const f of [entryPrice, exitPrice, quantity]) f.confidence = Math.min(f.confidence, 0.6);
    }
  }

  for (const f of [platform, instrument, direction, ...Object.values(nums)]) for (const m of f.flags) if (!warnings.includes(m)) warnings.push(m);

  const levels = (Array.isArray(o.chartLevels) ? o.chartLevels : [])
    .filter(isObj)
    .map((l) => ({ label: str(l.label, 40), price: typeof l.price === 'number' && Number.isFinite(l.price) && l.price > 0 ? l.price : NaN, kind: str(l.kind, 20) }))
    .filter((l) => Number.isFinite(l.price))
    .slice(0, 12);

  return {
    kind,
    legible,
    platform,
    instrument,
    direction,
    ...nums,
    levels,
    notes: str(o.notes, 300),
    warnings,
    usable: (kind === 'completed_trade' || kind === 'open_position') && entryPrice.value != null && instrument.value != null,
  };
}
